import { Pool } from 'pg';
import { drizzle, NodePgDatabase } from 'drizzle-orm/node-postgres';
import { eq, sql } from 'drizzle-orm';
import * as schema from './schema';

export interface NormalizedPathInfo {
  originalPath: string;
  absolutePath: string;
  repository?: {
    gitRoot: string;
    relativePath: string;
    remoteUrl?: string;
    owner?: string;
    repo?: string;
  };
  displayPath: string;
}

export interface NormalizedToolCall {
  sessionId: string;
  toolName: string;
  toolInput: any;
  toolResponse?: any;
  files?: NormalizedPathInfo[];
  repositoryRoot?: string;
  repositoryName?: string;
  repositoryOwner?: string;
  repositoryBranch?: string;
  repositoryHeadCommit?: string;
  directory?: string;
  startTimestamp: Date;
  endTimestamp?: Date;
  success?: boolean;
  errorMessage?: string;
}

export interface NormalizedEvent {
  eventType: string;
  sessionId: string;
  workingDirectory?: string;
  normalizedWorkingDirectory?: string;
  transcriptPath?: string;
  timestamp: number | Date;
  provider?: string;
  toolName?: string;
  toolInput?: any;
  toolOutput?: any;
  toolResponse?: any;
  files?: NormalizedPathInfo[];
  data?: any;
  raw?: any;
  // Repository information as nested object
  repository?: {
    gitRoot: string;
    remoteUrl?: string;
    owner?: string;
    repo?: string;
    branch?: string;
    headCommit?: string;
  };
  // Additional fields for specific event types
  startTimestamp?: Date;
  endTimestamp?: Date;
  success?: boolean;
  errorMessage?: string;
  directory?: string;
  // Legacy fields for backward compatibility
  repositoryRoot?: string;
  repositoryName?: string;
  repositoryOwner?: string;
  repositoryRepo?: string;
}

export interface NormalizedSession {
  id: string;
  repositories?: Array<{
    root: string;
    name: string;
    directories: Array<{
      path: string;
      fileCount: number;
    }>;
  }>;
}

export class ObservabilitySDK {
  private pool: Pool;
  private db: NodePgDatabase<typeof schema>;

  constructor(databaseUrl: string) {
    this.pool = new Pool({
      connectionString: databaseUrl,
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });
    this.db = drizzle(this.pool, { schema });
  }

  /**
   * Process any normalized event and route to appropriate table
   */
  async processEvent(event: NormalizedEvent): Promise<void> {
    // Debug logging
    console.log('[ObservabilitySDK] Processing event type:', event.eventType);
    console.log('[ObservabilitySDK] Event data:', JSON.stringify(event, null, 2));

    // Validate sessionId for all events
    if (!event.sessionId) {
      console.error('[ObservabilitySDK] ERROR: sessionId is required for all events');
      throw new Error('sessionId is required');
    }

    // Route based on event type
    switch (event.eventType) {
      case 'tool-use':
      case 'PreToolUse':
      case 'PostToolUse':
        return this.handleToolEvent(event);

      case 'session-start':
      case 'SessionStart':
        return this.handleSessionStart(event);

      case 'session-end':
      case 'SessionEnd':
        return this.handleSessionEnd(event);

      case 'user-prompt':
      case 'UserPromptSubmit':
        return this.handleUserPrompt(event);

      case 'subagent-stop':
      case 'SubagentStop':
        return this.handleSubagentStop(event);

      case 'stop':
      case 'Stop':
        return this.handleStop(event);

      case 'notification':
      case 'Notification':
        return this.handleNotification(event);

      default:
        console.warn('[ObservabilitySDK] Unknown event type:', event.eventType);
        // Don't throw error, just log and continue
        return;
    }
  }

  private async handleToolEvent(event: NormalizedEvent): Promise<void> {
    if (!event.toolName) {
      console.error('[ObservabilitySDK] Tool event missing toolName:', event);
      throw new Error('toolName is required for tool events');
    }

    // Extract repository info from event.repository or fall back to legacy fields
    let repositoryName = event.repository?.repo || event.repositoryName;
    let repositoryRoot = event.repository?.gitRoot || event.repositoryRoot || event.normalizedWorkingDirectory;
    let repositoryOwner = event.repository?.owner || event.repositoryOwner;
    let repositoryBranch = event.repository?.branch;
    let repositoryHeadCommit = event.repository?.headCommit;

    // If still no repository name, try to extract from path
    if (!repositoryName && repositoryRoot) {
      const pathParts = repositoryRoot.split('/');
      repositoryName = pathParts[pathParts.length - 1];
    } else if (!repositoryName && event.normalizedWorkingDirectory) {
      const pathParts = event.normalizedWorkingDirectory.split('/');
      repositoryName = pathParts[pathParts.length - 1];
    }

    // Convert to NormalizedToolCall format for backward compatibility
    const toolCall: NormalizedToolCall = {
      sessionId: event.sessionId,
      toolName: event.toolName,
      toolInput: event.toolInput || event.raw?.tool_input || {},
      toolResponse: event.toolResponse || event.toolOutput || event.raw?.tool_response,
      files: event.files,
      repositoryRoot: repositoryRoot,
      repositoryName: repositoryName,
      repositoryOwner: repositoryOwner,
      repositoryBranch: repositoryBranch,
      repositoryHeadCommit: repositoryHeadCommit,
      directory: event.directory,
      startTimestamp: event.startTimestamp || new Date(event.timestamp),
      endTimestamp: event.endTimestamp,
      success: event.success,
      errorMessage: event.errorMessage,
    };

    return this.insertNormalizedToolCall(toolCall);
  }

  private async handleSessionStart(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    await this.db.insert(schema.sessionStartLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'SessionStart',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      source: raw.source,
      user: raw.user,
      hostname: raw.hostname,
      workingDirectory: event.workingDirectory || raw.working_directory || raw.cwd,
      platform: raw.platform,
      shell: raw.shell,
      timestamp: new Date(event.timestamp),
    });
  }

  private async handleSessionEnd(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    await this.db.insert(schema.sessionEndLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'SessionEnd',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      cwd: event.workingDirectory || raw.cwd,
      reason: raw.reason,
      sessionStats: raw.session_stats ? JSON.stringify(raw.session_stats) : null,
      timestamp: new Date(event.timestamp),
    });
  }

  private async handleUserPrompt(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    const data = event.data || {};
    const prompt = data.prompt || raw.prompt;

    if (!prompt) {
      console.warn('[ObservabilitySDK] User prompt event missing prompt text');
      return;
    }

    await this.db.insert(schema.userPromptLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'UserPromptSubmit',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      cwd: event.workingDirectory || raw.cwd,
      prompt: prompt,
      characterCount: prompt.length,
      wordCount: prompt.split(/\s+/).length,
      timestamp: new Date(event.timestamp),
    });
  }

  private async handleSubagentStop(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    const data = event.data || {};

    await this.db.insert(schema.subagentStopLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'SubagentStop',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      stopHookActive: data.stopHookActive ?? raw.stop_hook_active ?? false,
      completionType: data.completionType || raw.completion_type,
      timestamp: new Date(event.timestamp),
    });
  }

  private async handleStop(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    const data = event.data || {};

    await this.db.insert(schema.stopLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'Stop',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      cwd: event.workingDirectory || raw.cwd,
      stopHookActive: data.stopHookActive ?? raw.stop_hook_active ?? false,
      permissionMode: raw.permission_mode,
      timestamp: new Date(event.timestamp),
    });
  }

  private async handleNotification(event: NormalizedEvent): Promise<void> {
    const raw = event.raw || {};
    const data = event.data || {};
    const message = data.message || raw.message;

    if (!message) {
      console.warn('[ObservabilitySDK] Notification event missing message');
      return;
    }

    await this.db.insert(schema.notificationLogs).values({
      id: crypto.randomUUID(),
      sessionId: event.sessionId,
      hookEventName: raw.hook_event_name || 'Notification',
      transcriptPath: event.transcriptPath || raw.transcript_path,
      cwd: event.workingDirectory || raw.cwd,
      message: message,
      timestamp: new Date(event.timestamp),
    });
  }

  /**
   * Insert a normalized tool call with repository information
   * @deprecated Use processEvent() instead
   */
  async insertNormalizedToolCall(data: NormalizedToolCall): Promise<void> {
    // Validate required fields
    if (!data.toolName) {
      console.error('[ObservabilitySDK] ERROR: toolName is required but was:', data.toolName);
      throw new Error('toolName is required for insertNormalizedToolCall');
    }

    if (!data.sessionId) {
      console.error('[ObservabilitySDK] ERROR: sessionId is required but was:', data.sessionId);
      throw new Error('sessionId is required for insertNormalizedToolCall');
    }

    const toolCallId = crypto.randomUUID();

    // Enhance tool_input with normalized path data
    const enhancedToolInput = {
      ...data.toolInput,
      // Add normalized repository data
      repository_root: data.repositoryRoot,
      repository_name: data.repositoryName,
      repository_owner: data.repositoryOwner,
      repository_branch: data.repositoryBranch,
      repository_head_commit: data.repositoryHeadCommit,
      directory: data.directory,
      // Add normalized file paths
      normalized_files: data.files,
    };

    // Insert into pre_hook_logs with enhanced data
    await this.db.insert(schema.preHookLogs).values({
      id: crypto.randomUUID(),
      toolCallId,
      sessionId: data.sessionId,
      toolName: data.toolName,
      toolInput: JSON.stringify(enhancedToolInput),
      hookEventName: 'PreToolUse',
      startTimestamp: data.startTimestamp,
      timestamp: new Date(),
      cwd: data.repositoryRoot || process.cwd(),
    });

    // If we have response data, insert post hook log
    if (data.endTimestamp && data.toolResponse !== undefined) {
      const enhancedToolResponse = {
        ...data.toolResponse,
        repository_root: data.repositoryRoot,
        repository_name: data.repositoryName,
        repository_owner: data.repositoryOwner,
        repository_branch: data.repositoryBranch,
        repository_head_commit: data.repositoryHeadCommit,
        directory: data.directory,
      };

      await this.db.insert(schema.postHookLogs).values({
        id: crypto.randomUUID(),
        toolCallId,
        sessionId: data.sessionId,
        toolName: data.toolName,
        toolResponse: JSON.stringify(enhancedToolResponse),
        hookEventName: 'PostToolUse',
        success: data.success ?? true,
        errorMessage: data.errorMessage,
        endTimestamp: data.endTimestamp,
        timestamp: new Date(),
        cwd: data.repositoryRoot || process.cwd(),
        durationMs: data.endTimestamp.getTime() - data.startTimestamp.getTime(),
      });
    }
  }

  /**
   * Batch insert normalized tool calls
   */
  async batchInsertNormalizedToolCalls(
    toolCalls: NormalizedToolCall[]
  ): Promise<{ inserted: number; errors: string[] }> {
    const errors: string[] = [];
    let inserted = 0;

    for (const toolCall of toolCalls) {
      try {
        await this.insertNormalizedToolCall(toolCall);
        inserted++;
      } catch (error) {
        errors.push(`Failed to insert tool call: ${error}`);
      }
    }

    return { inserted, errors };
  }

  /**
   * Update session with repository analysis
   */
  async updateSessionWithRepositoryData(data: NormalizedSession): Promise<void> {
    // Store repository data in session description as JSON for now
    const repositoryAnalysis = {
      repositories: data.repositories,
      analyzed_at: new Date().toISOString(),
    };

    await this.db
      .update(schema.sessions)
      .set({
        description: JSON.stringify(repositoryAnalysis),
      })
      .where(eq(schema.sessions.id, data.id));
  }

  /**
   * Get all unique repositories from the database
   * For now, extracts from tool_input JSON stored as text
   */
  async getRepositories() {
    const query = sql`
      WITH parsed_repos AS (
        SELECT DISTINCT
          session_id,
          CASE
            WHEN tool_input LIKE '%"repository_root":%'
            THEN json_extract_path_text(tool_input::json, 'repository_root')
            ELSE NULL
          END as repository_root,
          CASE
            WHEN tool_input LIKE '%"repository_name":%'
            THEN json_extract_path_text(tool_input::json, 'repository_name')
            ELSE NULL
          END as repository_name,
          CASE
            WHEN tool_input LIKE '%"repository_owner":%'
            THEN json_extract_path_text(tool_input::json, 'repository_owner')
            ELSE NULL
          END as repository_owner,
          CASE
            WHEN tool_input LIKE '%"repository_branch":%'
            THEN json_extract_path_text(tool_input::json, 'repository_branch')
            ELSE NULL
          END as repository_branch,
          CASE
            WHEN tool_input LIKE '%"repository_head_commit":%'
            THEN json_extract_path_text(tool_input::json, 'repository_head_commit')
            ELSE NULL
          END as repository_head_commit,
          timestamp
        FROM pre_hook_logs
        WHERE tool_input IS NOT NULL
      )
      SELECT
        repository_root,
        COALESCE(
          repository_name,
          CASE
            WHEN repository_root IS NOT NULL
            THEN split_part(repository_root, '/', -1)
            ELSE NULL
          END
        ) as repository_name,
        repository_owner,
        MAX(repository_branch) as latest_branch,
        MAX(repository_head_commit) as latest_commit,
        COUNT(DISTINCT session_id) as session_count,
        COUNT(*) as total_events,
        MAX(timestamp) as last_activity
      FROM parsed_repos
      WHERE repository_root IS NOT NULL OR repository_name IS NOT NULL
      GROUP BY repository_root, repository_name, repository_owner
      ORDER BY last_activity DESC
    `;

    const result = await this.db.execute(query);
    return result.rows;
  }

  /**
   * Get sessions that worked on a specific repository by name
   * @param repositoryName - The repository name (e.g., "a24z-observability")
   */
  async getSessionsByRepository(repositoryName: string) {
    const query = sql`
      WITH repo_sessions AS (
        SELECT DISTINCT
          pre.session_id,
          pre.id,
          pre.timestamp,
          pre.tool_call_id,
          CASE
            WHEN pre.tool_input LIKE '%"repository_name":%'
            THEN json_extract_path_text(pre.tool_input::json, 'repository_name')
            WHEN pre.tool_input LIKE '%"repository_root":%'
            THEN split_part(json_extract_path_text(pre.tool_input::json, 'repository_root'), '/', -1)
            ELSE NULL
          END as extracted_repo_name,
          CASE
            WHEN pre.tool_input LIKE '%"directory":%'
            THEN json_extract_path_text(pre.tool_input::json, 'directory')
            ELSE NULL
          END as directory
        FROM pre_hook_logs pre
        WHERE pre.tool_input IS NOT NULL
      )
      SELECT
        rs.session_id,
        MIN(rs.timestamp) as session_start,
        MAX(rs.timestamp) as session_end,
        COUNT(DISTINCT rs.id) as tool_count,
        SUM(CASE WHEN post.success = true THEN 1 ELSE 0 END) as successful_tools,
        SUM(CASE WHEN post.success = false THEN 1 ELSE 0 END) as failed_tools,
        ARRAY_AGG(DISTINCT rs.directory) FILTER (WHERE rs.directory IS NOT NULL) as directories_touched
      FROM repo_sessions rs
      LEFT JOIN post_hook_logs post ON rs.tool_call_id = post.tool_call_id
      WHERE rs.extracted_repo_name = ${repositoryName}
      GROUP BY rs.session_id
      ORDER BY session_start DESC
    `;

    const result = await this.db.execute(query);
    return result.rows;
  }

  /**
   * Get all events for a session in chronological order
   */
  async getSessionEvents(sessionId: string) {
    // Fetch all event types for this session
    const [
      toolEvents,
      sessionStarts,
      sessionEnds,
      userPrompts,
      subagentStops,
      stops,
      notifications
    ] = await Promise.all([
      // Tool events (pre and post hooks combined)
      this.db.execute(sql`
        SELECT
          'tool' as event_type,
          pre.tool_name,
          pre.tool_input,
          pre.timestamp as start_timestamp,
          post.tool_response,
          post.success,
          post.error_message,
          post.duration_ms,
          post.timestamp as end_timestamp,
          pre.cwd,
          pre.transcript_path
        FROM pre_hook_logs pre
        LEFT JOIN post_hook_logs post ON pre.tool_call_id = post.tool_call_id
        WHERE pre.session_id = ${sessionId}
        ORDER BY pre.timestamp
      `),

      // Session start events
      this.db.execute(sql`
        SELECT
          'session_start' as event_type,
          timestamp,
          working_directory,
          platform,
          shell,
          source,
          hostname,
          transcript_path
        FROM session_start_logs
        WHERE session_id = ${sessionId}
      `),

      // Session end events
      this.db.execute(sql`
        SELECT
          'session_end' as event_type,
          timestamp,
          reason,
          session_stats,
          cwd,
          transcript_path
        FROM session_end_logs
        WHERE session_id = ${sessionId}
      `),

      // User prompts
      this.db.execute(sql`
        SELECT
          'user_prompt' as event_type,
          timestamp,
          prompt,
          character_count,
          word_count,
          cwd,
          transcript_path
        FROM user_prompt_logs
        WHERE session_id = ${sessionId}
      `),

      // Subagent stops
      this.db.execute(sql`
        SELECT
          'subagent_stop' as event_type,
          timestamp,
          stop_hook_active,
          completion_type,
          transcript_path
        FROM subagent_stop_logs
        WHERE session_id = ${sessionId}
      `),

      // Main session stops
      this.db.execute(sql`
        SELECT
          'stop' as event_type,
          timestamp,
          stop_hook_active,
          permission_mode,
          cwd,
          transcript_path
        FROM stop_logs
        WHERE session_id = ${sessionId}
      `),

      // Notifications
      this.db.execute(sql`
        SELECT
          'notification' as event_type,
          timestamp,
          message,
          cwd,
          transcript_path
        FROM notification_logs
        WHERE session_id = ${sessionId}
      `)
    ]);

    // Combine all events and sort by timestamp
    const allEvents = [
      ...toolEvents.rows,
      ...sessionStarts.rows,
      ...sessionEnds.rows,
      ...userPrompts.rows,
      ...subagentStops.rows,
      ...stops.rows,
      ...notifications.rows
    ].sort((a: any, b: any) => {
      const timeA = new Date(a.timestamp || a.start_timestamp).getTime();
      const timeB = new Date(b.timestamp || b.start_timestamp).getTime();
      return timeA - timeB;
    });

    return allEvents;
  }

  /**
   * Get repository statistics
   */
  async getRepositoryStats(repositoryRoot?: string) {
    const query = sql`
      SELECT
        tool_input->>'repository_root' as repository_root,
        tool_input->>'repository_name' as repository_name,
        tool_input->>'directory' as directory,
        COUNT(DISTINCT session_id) as session_count,
        COUNT(*) as operation_count,
        SUM(CASE WHEN post.success = true THEN 1 ELSE 0 END) as successful_operations,
        SUM(CASE WHEN post.success = false THEN 1 ELSE 0 END) as failed_operations,
        AVG(post.duration_ms) as avg_duration
      FROM pre_hook_logs pre
      LEFT JOIN post_hook_logs post ON pre.tool_call_id = post.tool_call_id
      WHERE tool_input->>'repository_root' IS NOT NULL
      ${repositoryRoot ? sql`AND tool_input->>'repository_root' = ${repositoryRoot}` : sql``}
      GROUP BY
        tool_input->>'repository_root',
        tool_input->>'repository_name',
        tool_input->>'directory'
      ORDER BY operation_count DESC
    `;

    const result = await this.db.execute(query);
    return result.rows;
  }

  /**
   * Get problematic directories (high failure rate)
   */
  async getProblematicDirectories(minOperations = 10, maxResults = 20) {
    const query = sql`
      SELECT
        tool_input->>'repository_root' as repository_root,
        tool_input->>'directory' as directory,
        COUNT(*) as total_operations,
        SUM(CASE WHEN post.success = false THEN 1 ELSE 0 END) as failed_operations,
        ROUND(
          (SUM(CASE WHEN post.success = false THEN 1 ELSE 0 END)::float / COUNT(*)::float) * 100,
          2
        ) as failure_rate
      FROM pre_hook_logs pre
      LEFT JOIN post_hook_logs post ON pre.tool_call_id = post.tool_call_id
      WHERE tool_input->>'repository_root' IS NOT NULL
        AND tool_input->>'directory' IS NOT NULL
      GROUP BY
        tool_input->>'repository_root',
        tool_input->>'directory'
      HAVING COUNT(*) >= ${minOperations}
      ORDER BY failure_rate DESC
      LIMIT ${maxResults}
    `;

    const result = await this.db.execute(query);
    return result.rows;
  }

  /**
   * Close database connection
   */
  async close(): Promise<void> {
    await this.pool.end();
  }
}

// Export convenience function
export function createSDK(databaseUrl: string): ObservabilitySDK {
  return new ObservabilitySDK(databaseUrl);
}