/**
 * Subagent Stop logs table
 */
export const subagentStopLogs = pgTable("subagent_stop_logs", {
  id: uuid("id").primaryKey().defaultRandom(),
  sessionId: uuid("session_id").notNull(),
  hookEventName: text("hook_event_name").notNull(),
  transcriptPath: text("transcript_path"),
  stopHookActive: boolean("stop_hook_active").notNull(),
  completionType: text("completion_type"),
  timestamp: timestamp("timestamp").notNull().defaultNow(),
  organizationId: text("organization_id"),
  userId: text("user_id"),
});

/**
 * Stop logs table - for main session stop events
 */
export const stopLogs = pgTable("stop_logs", {
  id: uuid("id").primaryKey().defaultRandom(),
  sessionId: uuid("session_id").notNull(),
  hookEventName: text("hook_event_name").notNull(),
  transcriptPath: text("transcript_path"),
  cwd: text("cwd"),
  stopHookActive: boolean("stop_hook_active").notNull(),
  permissionMode: text("permission_mode"),
  timestamp: timestamp("timestamp").notNull().defaultNow(),
  organizationId: text("organization_id"),
  userId: text("user_id"),
});

/**
 * Notification logs table
 */
export const notificationLogs = pgTable("notification_logs", {
  id: uuid("id").primaryKey().defaultRandom(),
  sessionId: uuid("session_id").notNull(),
  hookEventName: text("hook_event_name").notNull(),
  transcriptPath: text("transcript_path"),
  cwd: text("cwd"),
  message: text("message").notNull(),
  timestamp: timestamp("timestamp").notNull().defaultNow(),
  organizationId: text("organization_id"),
  userId: text("user_id"),
});

// Type exports for TypeScript
export type Session = typeof sessions.$inferSelect;
export type NewSession = typeof sessions.$inferInsert;
export type PreHookLog = typeof preHookLogs.$inferSelect;
export type NewPreHookLog = typeof preHookLogs.$inferInsert;
export type PostHookLog = typeof postHookLogs.$inferSelect;
export type NewPostHookLog = typeof postHookLogs.$inferInsert;
export type UserPromptLog = typeof userPromptLogs.$inferSelect;
export type NewUserPromptLog = typeof userPromptLogs.$inferInsert;
export type SessionStartLog = typeof sessionStartLogs.$inferSelect;
export type NewSessionStartLog = typeof sessionStartLogs.$inferInsert;
export type SessionEndLog = typeof sessionEndLogs.$inferSelect;
export type NewSessionEndLog = typeof sessionEndLogs.$inferInsert;
export type SubagentStopLog = typeof subagentStopLogs.$inferSelect;
export type NewSubagentStopLog = typeof subagentStopLogs.$inferInsert;
export type StopLog = typeof stopLogs.$inferSelect;
export type NewStopLog = typeof stopLogs.$inferInsert;
export type NotificationLog = typeof notificationLogs.$inferSelect;
export type NewNotificationLog = typeof notificationLogs.$inferInsert;